(* A toy node. Don't change the type. *)
type node = { id : int; op : string; src : node list }

(* create () returns a fresh make function with its own table.
   make op src returns the SAME node (==) when called again with the same
   op and the same source nodes, and otherwise a new node with the next id:
   0, 1, 2, ... *)
let create () : string -> node list -> node =
  fun op src -> { id = 0; op; src }
